entries[22388] = { ["name"] = "Pläne: Gamaschen der Titanen", ["text"] = "Benötigt Schmiedekunst (300)\nBenutzen: Lehrt Euch die Herstellung von Gamaschen der Titanen.\nVerkaufspreis:\nGamaschen der Titanen\nWird beim Anlegen gebunden\nBeine Platte\n683 Rüstung\n+30 Stärke\nHaltbarkeit 120 / 120\nBenötigt Stufe 55\nAnlegen: Erhöht Eure Trefferwertung um 20.\nAnlegen: Erhöht Eure kritische Trefferwertung um 14.\nVerkaufspreis:\nBenötigt Arkanitbarren (12), Verzauberter Thoriumbarren (20), Essenz der Erde (10), Fläschchen der Titanen (2)" }
