entries[22390] = { ["name"] = "Pläne: Willensbrecher", ["text"] = "Benötigt Schmiedekunst (300)\nBenutzen: Lehrt Euch die Herstellung des Willensbrechers.\nVerkaufspreis:\nWillensbrecher\nWird beim Anlegen gebunden\nWaffenhand Streitkolben\n86 - 161 Schaden Tempo 2.70\n(45.74 Schaden pro Sekunde)\nHaltbarkeit 105 / 105\nBenötigt Stufe 58\nAnlegen: Erhöht Eure Trefferwertung um 10.\nAnlegen: Erhöht Eure kritische Trefferwertung um 14.\nVerkaufspreis:\nBenötigt Arkanitbarren (15), Dunkeleisenbarren (10), Essenz des Untodes (20), Dunkelrune (20), Teufelssaurierleder (10), Schattenhaut (2)" }
entries[22392] = { ["name"] = "Formel: Zweihandwaffe - Beweglichkeit", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (290)\nBenötigt Holzschlundfeste\n- Freundlich\nBenutzen: Lehrt Euch, Zweihandwaffen dauerhaft so zu verzaubern, dass sie die Beweglichkeit um 25 erhöhen.\nEine Zweihandnahkampfwaffe dauerhaft verzaubern, sodass sie die Beweglichkeit um +25 erhöht.\nVerkaufspreis:" }
