entries[22736] = { ["name"] = "Andonisus, Der Seelenschlächter", ["text"] = "Stratholme\nHerbeigezauberter Gegenstand\nWird beim Aufheben gebunden\nEinzigartig\nDauer: 5 min (Realzeit)Waffenhand Schwert\n159 - 296 Schaden Tempo 2.80\n(81.25 Schaden pro Sekunde)\nHaltbarkeit 125 / 125\nBenötigt Stufe 60\nAnlegen: Erhöht die Nahkampf- und Distanzangriffskraft um 600.\n\"Die Klinge scheint aus dieser Existenzebene zu verblassen. Es sieht aus, als sei sie nicht von dieser Welt.\"" }
entries[22737] = { ["name"] = "Atiesh, Hohestab des Wächters", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenötigt Stufe 60\nBenutzen: Befreit Atiesh vom verderblichen Einfluss von Sargeras. Nur auf geheiligtem Boden zu benutzen. (15 Min Abklingzeit)\n\"Ein Wesen von großer Bösartigkeit ist in diesem Stab gefangen.\"" }
entries[22739] = { ["name"] = "Foliant der Verwandlung: Schildkröte", ["text"] = "Klassen: Magier\nBenötigt Stufe 60\nBenutzen: Lehrt Verwandlung: Schildkröte.\nVerwandelt den Feind in eine Schildkröte und zwingt ihn, 50 Sek. lang so herumzuwandern. Während die Schildkröte herumwandert, kann sie weder angreifen noch Zauber wirken, regeneriert sich aber sehr schnell. Jeglicher erlittene Schaden verwandelt das Ziel in seine normale Gestalt zurück. Es kann immer nur jeweils ein Ziel verwandelt werden. Wirkt nur bei Wildtieren, Humanoiden und Tieren.\nVerkaufspreis:" }
