entries[22900] = { ["name"] = "Rezept: Elixier der Tarnung", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Alchimie (305)\nBenutzen: Lehrt euch, wie man ein Elixier der Tarnung herstellt.\nVerkaufspreis:\nElixier der Tarnung\nBenötigt Stufe 50\nBenutzen: Anwender kann 1 Stunde lang nicht aufgespürt werden. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Zottelkappe , Teufelsgras , Magieerfüllte Phiole" }
entries[22901] = { ["name"] = "Rezept: Schleichtrank", ["text"] = "Benötigt Alchimie (315)\nBenutzen: Lehrt Euch die Herstellung eines Schleichtranks.\nVerkaufspreis:\nSchleichtrank\nBenötigt Stufe 50\nBenutzen: Erhöht Eure Verstohlenheit 1 Min. lang um einen großen Betrag. (2 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Zottelkappe (2), Teufelsgras , Magieerfüllte Phiole" }
entries[22902] = { ["name"] = "Rezept: Elixier der erheblichen Frostmacht", ["text"] = "Benötigt Alchimie (320)\nBenutzen: Lehrt Euch die Herstellung eines Elixiers der erheblichen Frostmacht.\nVerkaufspreis:\nElixier der erheblichen Frostmacht\nBenötigt Stufe 50\nBenutzen: Erhöht den Schaden von Frostzaubern 1 Stunde lang um 55. Kampfelixier. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Wasserpartikel (2), Urflechte , Magieerfüllte Phiole" }
entries[22903] = { ["name"] = "Rezept: Trank der Wahnsinnsstärke", ["text"] = "Benötigt Alchimie (320)\nBenutzen: Lehrt Euch die Herstellung eines Tranks der Wahnsinnsstärke.\nVerkaufspreis:\nTrank der Wahnsinnsstärke\nBenötigt Stufe 50\nBenutzen: Erhöht Eure Stärke um 120 und verringert Eure Verteidigungswertung um 75. Hält 15 Sek. lang an. (2 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Terozapfen (3), Magieerfüllte Phiole" }
