entries[22905] = { ["name"] = "Rezept: Elixier der erheblichen Beweglichkeit", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Alchimie (330)\nBenötigt Ehrenfeste\n- Wohlwollend\nBenutzen: Lehrt Euch die Herstellung eines Elixiers der erheblichen Beweglichkeit.\nVerkaufspreis:\nElixier der erheblichen Beweglichkeit\nBenötigt Stufe 55\nBenutzen: Erhöht 1 Stunde lang Eure Beweglichkeit um 35 und Eure kritische Trefferwertung um 20. Kampfelixier. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Terozapfen , Teufelsgras (2), Magieerfüllte Phiole" }
