entries[23059] = { ["name"] = "Ring des Schreckenspanzers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+27 Ausdauer\nKlassen: Krieger\nBenötigt Stufe 60\nAnlegen: Erhöht Eure Ausweichwertung um 12.\nAnlegen: Erhöht Verteidigungswertung um 15.\n\nSchlachtrüstung des Schreckenspanzers (0/9)\nArmschienen des Schreckenspanzers\nBrustplatte des Schreckenspanzers\nStulpen des Schreckenspanzers\nTaillenschutz des Schreckenspanzers\nHelm des Schreckenspanzers\nBeinplatten des Schreckenspanzers\nSchulterstücke des Schreckenspanzers\nSabatons des Schreckenspanzers\nRing des Schreckenspanzers\n(2) Set : Erhöht den Schaden, der von Eurer Fähigkeit 'Rache' verursacht wird, um 75.\n(4) Set : Erhöht Eure Trefferchance mit den Fähigkeiten 'Spott' und 'Herausforderungsruf' um 5%.\n(6) Set : Erhöht Eure Trefferchance mit den Fähigkeiten 'Rüstung zerreißen', 'Verwüsten', 'Heldenhafter Stoß', 'Rache' und 'Schildschlag' um 5%.\n(8) Set : Wenn Eure Gesundheit unter 20% sinkt, helfen Euch Heilzauber, die in den nächsten 5 Sekunden gewirkt werden, dem Tod von der Schippe zu springen, indem die Heilung um bis zu 160 erhöht wird.\nVerkaufspreis:" }
entries[23060] = { ["name"] = "Ring der Knochensense", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+20 Stärke\n+20 Beweglichkeit\n+10 Ausdauer\nKlassen: Schurke\nBenötigt Stufe 60\nAnlegen: Erhöht Eure Trefferwertung um 10.\n\nRüstung der Knochensense (0/9)\nArmschienen der Knochensense\nBrustplatte der Knochensense\nStulpen der Knochensense\nHelm der Knochensense\nBeinplatten der Knochensense\nSchulterstücke der Knochensense\nSabatons der Knochensense\nTaillenschutz der Knochensense\nRing der Knochensense\n(2) Set : Eure normalen Nahkampfangriffe haben eine Chance, Euch zu stärken, und heilen Euch um 90 bis 110.\n(4) Set : Kritische Treffer mit Euren Fähigkeiten 'Meucheln', 'Finsterer Stoß' und 'Blutsturz' stellen 5 Energie wieder her.\n(6) Set : Verringert die von Euren Fähigkeiten 'Meucheln', 'Finsterer Stoß', 'Blutsturz' und 'Ausweiden' verursachte Bedrohung.\n(8) Set : Eure Fähigkeit 'Ausweiden' hat pro Combopunkt eine Chance, eine Schwachstelle in der Rüstung Eures Gegners aufzudecken, wodurch die nächste Anwendung Eurer Fähigkeiten 'Meucheln', 'Finsterer Stoß' oder 'Blutsturz' eine kritische Trefferchance von 100% erhält.\nVerkaufspreis:" }
entries[23061] = { ["name"] = "Ring des Glaubens", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+16 Intelligenz\n+16 Willenskraft\nKlassen: Priester\nBenötigt Stufe 60\nAnlegen: Erhöht durch sämtliche Zauber und magische Effekte verursachte Heilung um bis zu 55 und den verursachten Schaden um bis zu 19.\n\nGewänder des Glaubens (0/9)\nGürtel des Glaubens\nBindungen des Glaubens\nReif des Glaubens\nHandschuhe des Glaubens\nGamaschen des Glaubens\nRobe des Glaubens\nSandalen des Glaubens\nSchulterpolster des Glaubens\nRing des Glaubens\n(2) Set : Verringert die Manakosten Eures Zaubers 'Erneuerung' um 12%.\n(4) Set : Bei kritischen Treffern Eures Zaubers 'Große Heilung' erhält Euer Ziel eine 'Rüstung des Glaubens', welche bis zu 500 Schaden absorbiert.\n(6) Set : Verringert die durch Eure Heilzauber verursachte Bedrohung.\n(8) Set : Jeder gewirkte Zauber kann eine göttliche Offenbarung auslösen, die Eure Manaregeneration 30 Sek. lang um 24 erhöht. (Procchance: 5%)\nVerkaufspreis:" }
entries[23062] = { ["name"] = "Frostfeuerring", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+10 Ausdauer\n+10 Intelligenz\nKlassen: Magier\nBenötigt Stufe 60\nAnlegen: Erhöht durch Zauber und magische Effekte verursachten Schaden und Heilung um bis zu 30.\nAnlegen: Erhöht Eure kritische Zaubertrefferwertung um 14.\n\nFrostfeuerornat (0/9)\nFrostfeuergürtel\nFrostfeuerbindungen\nFrostfeuerreif\nFrostfeuerhandschuhe\nFrostfeuergamaschen\nFrostfeuerrobe\nFrostfeuersandalen\nFrostfeuerschulterpolster\nFrostfeuerring\n(2) Set : Verringert die Abklingzeit Eures Zaubers 'Hervorrufung' um 1 Min.\n(4) Set : Eure 'Magische Rüstung' erhält eine Chance, bei jedem Treffer durch einen Schadenszauber Euren Widerstand gegen diese Art der Magie 30 Sek. lang um 35 zu erhöhen. (Procchance: 20%)\n(6) Set : Eure Schadenszauber haben eine Chance, Euer Ziel bis zu 200 erhöhten Schaden durch nachfolgende Zauber erleiden zu lassen. (Procchance: 20%)\n(8) Set : Eure Schadenszauber haben eine Chance, Euch in einen Zustand der Verrückung zu versetzen, bei dem Euer nächster gewirkter Zauber keine Bedrohung verursacht. (Procchance: 15%)\nVerkaufspreis:" }
entries[23063] = { ["name"] = "Ring des verseuchten Herzens", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+24 Ausdauer\nKlassen: Hexenmeister\nBenötigt Stufe 60\nAnlegen: Erhöht durch Zauber und magische Effekte verursachten Schaden und Heilung um bis zu 29.\n\nRoben des verseuchten Herzens (0/9)\nGürtel des verseuchten Herzens\nBindungen des verseuchten Herzens\nReif des verseuchten Herzens\nHandschuhe des verseuchten Herzens\nGamaschen des verseuchten Herzens\nRobe des verseuchten Herzens\nSandalen des verseuchten Herzens\nSchulterpolster des verseuchten Herzens\nRing des verseuchten Herzens\n(2) Set : Eure Zauber 'Schattenblitz' erhalten eine Chance, Euch für 270 bis 330 zu heilen.\n(4) Set : Erhöht den durch Euren Zauber 'Verderbnis' zugefügten Schaden um 12%.\n(6) Set : Eure kritischen Treffer mit Zaubern erzeugen 25% weniger Bedrohung. Zusätzlich verursachen Verderbnis, Feuerbrand, Fluch der Pein und Lebensentzug 25% weniger Bedrohung.\n(8) Set : Verringert die Gesundheitskosten Eures Zaubers 'Aderlass' um 12%.\nVerkaufspreis:" }
entries[23064] = { ["name"] = "Ring des Traumwandlers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+16 Ausdauer\n+16 Intelligenz\n+16 Willenskraft\nKlassen: Druide\nBenötigt Stufe 60\nAnlegen: Erhöht durch sämtliche Zauber und magische Effekte verursachte Heilung um bis zu 37 und den verursachten Schaden um bis zu 13.\n\nGewandung des Traumwandlers (0/9)\nStiefel des Traumwandlers\nGurt des Traumwandlers\nHandschützer des Traumwandlers\nKopfstück des Traumwandlers\nBeinschützer des Traumwandlers\nSchiftung des Traumwandlers\nTunika des Traumwandlers\nHandgelenksschutz des Traumwandlers\nRing des Traumwandlers\n(2) Set : Bei jedem Wirkungsintervall Eures Zaubers 'Verjüngung' besteht eine Chance, dass beim Ziel 60 Mana, 8 Energie oder 2 Wut wiederhergestellt werden.\n(4) Set : Verringert die Manakosten Eurer Zauber 'Heilende Berührung', 'Nachwachsen', 'Verjüngung' und 'Gelassenheit' um 3%.\n(6) Set : Das erstmalige Wirken sowie jedes Wirkungsintervall von 'Nachwachsen' erhöhen die maximale Gesundheit Eures Ziels um bis zu 50. Bis zu 7-mal stapelbar.\n(8) Set : Bei kritischen Treffern Eures Zaubers 'Heilende Berührung' erhaltet Ihr 30% der Manakosten dieses Zaubers zurück.\nVerkaufspreis:" }
entries[23065] = { ["name"] = "Ring des Erdspalters", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+16 Ausdauer\n+16 Intelligenz\nKlassen: Schamane\nBenötigt Stufe 60\nAnlegen: Erhöht durch sämtliche Zauber und magische Effekte verursachte Heilung um bis zu 37 und den verursachten Schaden um bis zu 13.\nAnlegen: Stellt alle 5 Sek. 6 Mana wieder her.\n\nDer Erdspalter (0/9)\nStiefel des Erdspalters\nGurt des Erdspalters\nHandschützer des Erdspalters\nKopfstück des Erdspalters\nBeinschützer des Erdspalters\nSchiftung des Erdspalters\nTunika des Erdspalters\nHandgelenksschutz des Erdspalters\nRing des Erdspalters\n(2) Set : Verringert die Manakosten Eurer Totemzauber um 12%.\n(4) Set : Erhöht die durch Euer Totem der Manaquelle regenerierte Manamenge um 25%.\n(6) Set : Eure Zauber 'Welle der Heilung' und 'Geringe Welle der Heilung' haben eine Chance, Euer Ziel mit der 'Macht der Totems' magiezuerfüllen. (Procchance: 10%)\n(8) Set : Euer Zauber 'Blitzschlagschild' gewährt Euch zusätzlich alle 5 Sek. 15 Mana, solange er aktiv ist.\nVerkaufspreis:" }
entries[23066] = { ["name"] = "Ring der Erlösung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+16 Ausdauer\n+16 Intelligenz\nKlassen: Paladin\nBenötigt Stufe 60\nAnlegen: Erhöht durch sämtliche Zauber und magische Effekte verursachte Heilung um bis zu 37 und den verursachten Schaden um bis zu 13.\nAnlegen: Stellt alle 5 Sek. 6 Mana wieder her.\n\nRüstung der Erlösung (0/9)\nStiefel der Erlösung\nGurt der Erlösung\nHandschützer der Erlösung\nKopfstück der Erlösung\nBeinschützer der Erlösung\nSchiftung der Erlösung\nTunika der Erlösung\nHandgelenksschutz der Erlösung\nRing der Erlösung\n(2) Set : Erhöht den durch Euren Zauber 'Richturteil des Lichts' geheilten Wert um 20.\n(4) Set : Verringert die Abklingzeit Eures Zaubers 'Handauflegung' um 12 Min.\n(6) Set : Eure Zauber 'Lichtblitz' und 'Heiliges Licht' haben eine Chance, Euer Ziel mit heiliger Macht magiezuerfüllen. (Procchance: 10%)\n(8) Set : Euer Zauber 'Reinigung des Glaubens' heilt das Ziel zusätzlich um 200.\nVerkaufspreis:" }
